#include "mspa/psychology/reappraisal.hpp"
#include <algorithm>
namespace mspa {Result<void>ReappraisalSystem::reappraise_memory(AgentPsychState&a,MemoryId id,float l,float c)const{auto it=std::find_if(a.memories.begin(),a.memories.end(),[&](const auto&m){return m.id==id;});if(it==a.memories.end())return make_error(ErrorCode::InvalidArgument,"memory does not exist");it->emotional_load=std::clamp(l,-1.0f,1.0f);it->certainty=std::clamp(c,0.0f,1.0f);return {};}Result<void>ReappraisalSystem::reactivate_memory(AgentPsychState&a,MemoryId id)const{auto it=std::find_if(a.memories.begin(),a.memories.end(),[&](const auto&m){return m.id==id;});if(it==a.memories.end())return make_error(ErrorCode::InvalidArgument,"memory does not exist");++it->reactivations;it->importance=std::clamp(it->importance+0.05f,0.0f,1.0f);it->last_reactivated_at=a.last_processed_time;return {};}Result<void>ReappraisalSystem::reappraise_belief(AgentPsychState&a,BeliefId id,float load,float certainty,PsychTime now)const{auto it=std::find_if(a.beliefs.begin(),a.beliefs.end(),[&](const auto&b){return b.id==id;});if(it==a.beliefs.end())return make_error(ErrorCode::InvalidArgument,"belief does not exist");it->emotional_load=std::clamp(load,-1.0f,1.0f);it->certainty=std::clamp(certainty,0.0f,1.0f);it->updated_at=now;return {};}}
